import{H as e,_t as t,it as n,rt as r}from"./chunks/framework.Bcve9O8f.js";var i=JSON.parse(`{"title":"Answer system","description":"","frontmatter":{"title":"Answer system","head":[["meta",{"property":"og:title","content":"Answer system | Millennium Solutions"}],["meta",{"property":"og:description","content":"ℤ/9 vortex framework — recomputable proof of concept"}],["meta",{"property":"og:url","content":"https://ceccec.psg.bg/millennium-solutions/docs/ANSWER-SYSTEM.html"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"name":"twitter:title","content":"Answer system | Millennium Solutions"}],["meta",{"name":"twitter:description","content":"ℤ/9 vortex framework — recomputable proof of concept"}],["link",{"rel":"canonical","href":"https://ceccec.psg.bg/millennium-solutions/docs/ANSWER-SYSTEM.html"}],["link",{"rel":"alternate","hreflang":"en","href":"https://ceccec.psg.bg/millennium-solutions/docs/ANSWER-SYSTEM.html"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://ceccec.psg.bg/millennium-solutions/docs/ANSWER-SYSTEM.html"}]]},"headers":[],"relativePath":"docs/ANSWER-SYSTEM.md","filePath":"docs/ANSWER-SYSTEM.md"}`),a={name:`docs/ANSWER-SYSTEM.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="answer-system-true-false-or-unknown-each-with-a-certificate" tabindex="-1">Answer system: TRUE, FALSE, or UNKNOWN, each with a certificate <a class="header-anchor" href="#answer-system-true-false-or-unknown-each-with-a-certificate" aria-label="Permalink to “Answer system: TRUE, FALSE, or UNKNOWN, each with a certificate”">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to “Purpose”">​</a></h2><p>Answer a question with one of three values, and attach to every TRUE or FALSE a certificate that a reader can check without trusting the system:</p><ul><li><strong>TRUE</strong>: a certificate that the statement holds.</li><li><strong>FALSE</strong>: a certificate that it does not (a counterexample, or a refutation).</li><li><strong>UNKNOWN</strong>: no certificate was found. The answer names the blocking step.</li></ul><p>This is the intended meaning of the system. It does not claim that every question has a computable answer. Undecidable questions exist (the halting problem), and open problems such as the Clay problems have no certificate in this repository, so they answer UNKNOWN.</p><h2 id="answer-rules-no-exceptions" tabindex="-1">Answer rules (no exceptions) <a class="header-anchor" href="#answer-rules-no-exceptions" aria-label="Permalink to “Answer rules (no exceptions)”">​</a></h2><ol><li>TRUE requires a certificate of type C1 or C2 (below). Nothing else produces TRUE.</li><li>FALSE requires a counterexample certificate: a witness that the statement fails, checked by the same kernel.</li><li>A probable result is never TRUE or FALSE. It is UNKNOWN, with the probability named.</li><li>A cited source is evidence, not a certificate. A sourced answer is reported as SOURCED, never as TRUE.</li><li>A question that cannot be formalised is UNKNOWN, with the reason &quot;not formalised&quot;.</li><li>A refusal of any step is UNKNOWN with that step named.</li></ol><h2 id="certificate-types" tabindex="-1">Certificate types <a class="header-anchor" href="#certificate-types" aria-label="Permalink to “Certificate types”">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>What it is</th><th>Checked by</th><th>Yields</th></tr></thead><tbody><tr><td>C1</td><td>A Lean proof of the statement, no <code>sorry</code>, no axioms beyond the kernel&#39;s</td><td><code>lean_ask</code> (compile, <code>#print axioms</code>, sorry check)</td><td>TRUE</td></tr><tr><td>C2</td><td>An arithmetic witness: a factor with an exact product check, or a Miller–Rabin base proving compositeness</td><td><code>task_route</code> (exact integer arithmetic)</td><td>TRUE or FALSE</td></tr><tr><td>C3</td><td>A cited source: a DOI that resolves to the canonical record, or an arXiv identifier whose abstract page resolves to the stated title</td><td><code>answer-verify-doi</code> (DOI); <code>answer-verify-arxiv</code> (arXiv, through web_fetch)</td><td>SOURCED</td></tr><tr><td>C4</td><td>A probable-prime result, or a text question</td><td>none</td><td>UNKNOWN</td></tr></tbody></table><p>C2 applies only where the check is exact: a found factor passes <code>p × q = n</code>, and a composite is proved by a base whose failure is an exact congruence. A probable prime is C4, not C2.</p><h2 id="routing" tabindex="-1">Routing <a class="header-anchor" href="#routing" aria-label="Permalink to “Routing”">​</a></h2><ol><li>Integer (decimal or hexadecimal): <code>task_route</code>. Composite or small prime → C2. Probable prime → UNKNOWN.</li><li>Lean statement (a theorem with <code>:= by decide</code> or a tactic proof): <code>lean_ask</code>. Conjunctions are split by <code>lean_split</code>, and the whole holds only if every part does (C1 per part).</li><li>Text question: formalise it as a Lean statement first. If it cannot be formalised, UNKNOWN.</li><li>Claim about a publication: <code>doi-precedence-test</code>. Resolves to SOURCED, never TRUE.</li><li>Clay problems: UNKNOWN, with the reason that the statement is open. The Clay conditions are checked by <code>clay-conditions-test</code> and reported as NOT MET until the evidence exists.</li></ol><h2 id="output-shape" tabindex="-1">Output shape <a class="header-anchor" href="#output-shape" aria-label="Permalink to “Output shape”">​</a></h2><p>Every answer is JSON with these fields: <code>question</code>, <code>value</code> (TRUE, FALSE, SOURCED, or UNKNOWN), <code>certificate</code> (type, and the artefact a reader can check: a Lean file, a witness, or a DOI), <code>reason</code>, and <code>checkedBy</code> (the tool and the date). An UNKNOWN answer has <code>blockingStep</code> instead of <code>certificate</code>.</p><h2 id="todo-list" tabindex="-1">Todo list <a class="header-anchor" href="#todo-list" aria-label="Permalink to “Todo list”">​</a></h2><p>Each item is done only when its acceptance test passes. An item that is not done stays <code>[ ]</code>.</p><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-0" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-0"> T1 Types. <code>src/answer/types.ts</code> defines the answer, certificate, and value types above. Acceptance: a type error on an answer that has TRUE without a C1 or C2 certificate. Evidence: <code>scripts/answer-types-test.ts</code>, run through the MCP as suite <code>answer-types</code>: 11 of 11 cases.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-1" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-1"> T2 Router. <code>src/answer/route.ts</code> classifies a question as integer, Lean, text, publication claim, or Clay. Acceptance: a fixed table of inputs, each classified as stated in the Routing section. Evidence: the priority is decided in <code>src/proof/answer_route.lean</code> (exhaustive over the 16 feature combinations). The text reading stays in <code>src/answer/route.ts</code> and is not a finite domain.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-2" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-2"> T3 C1 verifier. Wraps <code>lean_ask</code>; returns TRUE only when compiles, no sorry, and no axioms. Evidence: the decision is in <code>src/proof/arith.lean</code> and <code>src/proof/answer.lean</code>. Every verdict of the arithmetic verifier is checked by the kernel in the answer path. Acceptance: the true test theorem returns TRUE, a false one returns UNKNOWN, a sorry one returns UNKNOWN.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-3" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-3"> T4 C2 verifier. Wraps <code>task_route</code>; returns TRUE or FALSE only from an exact witness. Evidence: <code>scripts/answer-arith-test.ts</code>, run through the MCP as suite <code>answer-arith</code>: 3 of 3 cases. Acceptance: 91 is FALSE with factor 7; 97 is TRUE; the probable prime input returns UNKNOWN.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-4" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-4"> T5 C3 verifier. Wraps <code>doi-precedence-test</code>; returns SOURCED only when the DOI resolves to the canonical record. Evidence: <code>scripts/answer-doi-test.ts</code>, run through the MCP as suite <code>answer-doi</code>: the canonical DOI is SOURCED, the other record is UNKNOWN. Acceptance: the canonical DOI returns SOURCED; a non-canonical DOI returns UNKNOWN.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-5" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-5"> T6 <code>answer</code> MCP tool. Routes through T2 to T3, T4, or T5, and returns the output shape above. Evidence: suite <code>answer-tool</code> through the MCP: an integer, a Lean theorem, the canonical DOI, a Clay problem, and a text question, each answered as the rules require. Acceptance: an e2e test calls it through the MCP for one input of each route.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-6" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-6"> T7 No-certificate gate. A test that fails if any answer carries TRUE or FALSE without a certificate. Evidence: <code>src/proof/answer_gate.lean</code> decides the rules, and <code>scripts/answer-gate.ts</code> asks the kernel for each stored answer; suite <code>answer-gate</code> refuses five planted violations and accepts a compliant set; real answers from the <code>answer</code> tool pass (4 of 4 after the output shape was fixed to name <code>checkedBy</code> and <code>blockingStep</code>). Acceptance: a planted answer with TRUE and no certificate is refused.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-7" disabled="disabled"><label class="task-list-item-label" for="task-item-7"> T8 Clay questions. Each of the six open problems answers UNKNOWN, with its blocking step recorded. Acceptance: six UNKNOWN answers, one per problem, each naming its formal status.</label></li></ul><h2 id="current-state-checked-not-assumed" tabindex="-1">Current state (checked, not assumed) <a class="header-anchor" href="#current-state-checked-not-assumed" aria-label="Permalink to “Current state (checked, not assumed)”">​</a></h2><ul><li>T3 and T4 exist as tools (<code>lean_ask</code>, <code>task_route</code>), but no <code>answer</code> tool joins them yet.</li><li>T5 exists as a test (<code>doi-precedence-test</code>), and its current run shows 1 of 4 DOIs resolving to the canonical record.</li><li>T6 to T8 do not exist.</li></ul><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to “Limits”">​</a></h2><ul><li>The system can only certify what it can formalise. Most open questions cannot be formalised in this repository.</li><li>A certificate is checked by this repository&#39;s tools. A reader who wants independence should re-run the checks with their own toolchain.</li></ul>`,21)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};